const math = require('mathjs');

const generate = () => {
    const mass = 5; // mass of the pendulum bob in kg
    const r = 2; // length of the cord in meters
    const g = 9.81; // acceleration due to gravity in m/s^2

    // 1. Initial Tension at theta = 0
    const theta_initial = 0;  // in degrees
    const T_initial = mass * g; // T = mg

    // 2. Tension at theta = 45 degrees
    const theta_rad = math.unit(45, 'degrees').toNumber('rad'); // Convert to radians
    const v_squared = 2 * g * r * (1 - math.cos(theta_rad)); // Derived from energy conservation
    const T_45 = mass * g * math.sin(theta_rad) + (mass * v_squared) / r; // T = mg*sin(theta) + (mv^2)/r

    return {
        params: {
            mass: mass,
            length: r,
            theta_initial: theta_initial,
            theta_45: 45,
        },
        correct_answers: {
            initial_tension: T_initial,
            tension_at_45: T_45,
        },
        nDigits: 3,
        sigfigs: 3
    };
};

module.exports = { generate };

