    masslabel = units[unitSystems[unitSel]].masslabel;    

    m = math.randomInt(10, 30); // mass of block B
    v = math.randomInt(5, 20); // speed of block B (arbitrary range)
    h = math.randomInt(40, 80); // height of the cone
    r = math.randomInt(30, 60); // horizontal distance from apex to block at speed

    // Determine angle theta using geometry of the cone 
    theta = math.atan(h / r); // height over radius

    // Tension (T) and Normal Reaction (N) equations derived from FBD
    T = (m * (v ** 2) / r) / math.cos(theta);
    N = (m * 9.81 * math.cos(theta) + T * math.sin(theta)) / math.cos(theta);

    // Return SVG string example
    let svgString = `<svg xmlns="http://www.w3.org/2000/svg" width="300" height="150">\n`;
    svgString += `  <line x1="0" y1="100" x2="${r}" y2="100" stroke="blue" stroke-width="2"/>\n`;
    svgString += `  <line x1="${r}" y1="100" x2="${r - 10 * math.cos(theta)}" y2="${100 - 10 * math.sin(theta)}" stroke="red" stroke-width="2"/>\n`;
    svgString += `  <text x="${r / 2}" y="90">Block B</text>\n`;
    svgString += `</svg>\n`;

    let data = {
        params: { 
            masslabel: masslabel,
            unitsMass: unitsMass,
            unitsDist: unitsDist,
            unitsForce: unitsForce,
            m: m,
            h: h,
            r: r,
        },
        correct_answers: {
