    }

    console.log(data);
    return data;
}

module.exports = {
    generate
};

const math = require('mathjs');

const generate = () => {
    const r_c = 0.4; // meters
    const weight = 0.5 * 9.81; // weight of the ball in Newtons (0.5 lb to SI)
    const theta = math.unit(30, 'degrees'); // theta in radians
    const dot_theta = 0.4; // rad/s
    const ddot_theta = 0.8; // rad/s^2

    // Compute radial position from theta
    const r = 2 * r_c * math.cos(theta);
    const dr_dt = -2 * r_c * math.sin(theta) * dot_theta; // Derivative of r with respect to time
    const d2r_dt2 = 2 * r_c * (-math.cos(theta) * dot_theta**2 - math.sin(theta) * ddot_theta); // Second derivative of r

    // Forces acting on the ball
    const m = weight / 9.81; // mass in kg
    const N = math.symbolic('N'); // Normal force

    // Radial motion equation
    const radial_equation = N * math.cos(theta) - weight * math.sin(theta) - (m * (d2r_dt2 - r * dot_theta**2));
    // Transverse motion equation
    const F_OA = math.symbolic('F_OA'); // Force of the arm on the ball
    const transverse_equation = F_OA + N * math.sin(theta) - weight * math.cos(theta) - (m * (r * ddot_theta + 2 * dr_dt * dot_theta));

    // Solve for N and F_OA symbolically
    // Using mathjs to solve the equations; Here we assume equalities hold at equilibrium points
    const solutions = math.solve([radial_equation, transverse_equation], [N, F_OA]);

    // Return parameters and answers
    data = {
        params: {
            weight: weight,
            theta: 30,
            r_c: r_c,
            unitForce: 'N'
        },
        correct_answers: {
            Normal_Force: solutions[N],
            Force_of_Arm: solutions[F_OA]
        },
        nDigits: 2,
        sigfigs: 2
    };

    console.log(data);
    return data;
};

generate();
module.exports = {
    generate
};

const math = require('mathjs');

const generate = () => {
    // Ingested parameters based on a structured query from HTML
    const r_c = 10; // Example radius, replace with dynamic input
    const theta = math.randomInt(15, 76); // Random angle between 15 and 75
    const dotTheta = math.random(0, 5); // Random angular velocity
    const ddotTheta = math.random(0, 5); // Random angular acceleration

    // Calculate r based on provided formula
    const r = 2 * r_c * Math.cos(math.unit(theta, 'deg').toNumber('rad'));

    // First derivative dot(r)
    const dotR = -2 * r_c * Math.sin(math.unit(theta, 'deg').toNumber('rad')) * dotTheta;

    // Second derivative (ddot(r)) using product and chain rule
    const ddotR = -2 * r_c * (Math.cos(math.unit(theta, 'deg').toNumber('rad')) * dotTheta * dotTheta) 
                 - 2 * r_c * Math.sin(math.unit(theta, 'deg').toNumber('rad')) * ddotTheta;

    return {
        params: {
            theta: theta,
            r_c: r_c,
            dotTheta: dotTheta,
            ddotTheta: ddotTheta,
        },
        correct_answers: {
            r: r,
            dotR: dotR,
            ddotR: ddotR
        },
        nDigits: 3,  // Decimal places.
        sigfigs: 3   // Significant figures.
    };
};

module.exports = { generate };
